import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Page Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"pages-and-user-interfaces/page-extensions.md","filePath":"pages-and-user-interfaces/page-extensions.md"}`),a={name:`pages-and-user-interfaces/page-extensions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="page-extensions" tabindex="-1">Page Extensions <a class="header-anchor" href="#page-extensions" aria-label="Permalink to “Page Extensions”">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2><p>A page extension allows us to extend an existing Business Central page without modifying its original definition.</p><p>For example, imagine Business Central already has a standard <code>Customer Card</code> page, but your organization wants to:</p><ul><li>Add additional fields.</li><li>Introduce new actions.</li><li>Rearrange existing fields.</li><li>Change the captions of existing controls.</li><li>Modify the behavior of certain controls.</li></ul><p>Instead of modifying Microsoft&#39;s original <code>Customer Card</code> object, we create a <strong>Page Extension</strong>.</p><p>This is part of Business Central&#39;s extensibility model, which allows developers to customize the application while keeping the original application objects intact.</p><h2 id="creating-a-page-extension" tabindex="-1">Creating a Page Extension <a class="header-anchor" href="#creating-a-page-extension" aria-label="Permalink to “Creating a Page Extension”">​</a></h2><p>We use the <code>pageextension</code> keyword to define a page extension.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to “Syntax”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension ObjectID ExtensionName extends TargetPage</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // Add or modify page controls.</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    actions</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // Add or modify page actions.</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        // Declare variables.</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Notice the following:</p><ul><li><code>ObjectID</code>: The unique ID assigned to the extension object.</li><li><code>ExtensionName</code>: The name of our page extension.</li><li><code>extends</code>: Specifies the existing page we want to extend.</li><li><code>layout</code>: Used to add, modify, or reposition controls.</li><li><code>actions</code>: Used to add, modify, or reposition actions.</li><li><code>var</code>: Used to declare variables for the extension.</li></ul><p><strong>Important:</strong> The target page must have its <code>Extensible</code> property set to <code>true</code>. Also, API pages cannot be extended using a page extension.</p><h2 id="adding-fields-to-existing-pages" tabindex="-1">Adding Fields to Existing Pages <a class="header-anchor" href="#adding-fields-to-existing-pages" aria-label="Permalink to “Adding Fields to Existing Pages”">​</a></h2><p>One of the most common uses of page extensions is adding new fields to an existing page.</p><p>Suppose we want to add a new field called <code>RewardPoints</code> to the standard Customer Card.</p><p>First, we need to understand something:</p><p>A page extension does not create new database fields. If we want to store additional data, we first need to create the field using a <strong>Table Extension</strong>.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tableextension 50100 CustomerTableExt extends Customer</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    fields</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(50100; RewardPoints; Integer)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Reward Points&#39;;</span></span>
<span class="line"><span>            DataClassification = CustomerContent;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Now that the field exists in the Customer table, we can display it on the Customer Card using a page extension.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50101 CustomerCardExt extends &quot;Customer Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        addlast(General)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            field(RewardPoints; Rec.RewardPoints)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                ApplicationArea = All;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>addlast(General)</code> tells Business Central to add the new field at the end of the existing <code>General</code> group.</p><p>Notice that we use <code>Rec.RewardPoints</code> to access the field we created in the Customer table extension.</p><p><strong>Remember:</strong> A table extension adds the database field; a page extension makes that field available on an existing page.</p><h2 id="adding-actions-to-existing-pages" tabindex="-1">Adding Actions to Existing Pages <a class="header-anchor" href="#adding-actions-to-existing-pages" aria-label="Permalink to “Adding Actions to Existing Pages”">​</a></h2><p>We can also introduce new actions to existing pages.</p><p>For example, let&#39;s add an action to the Customer Card that displays a message.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50101 CustomerCardExt extends &quot;Customer Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    actions</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        addlast(Processing)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            action(ShowCustomerInfo)</span></span>
<span class="line"><span>            {</span></span>
<span class="line"><span>                Caption = &#39;Show Customer Info&#39;;</span></span>
<span class="line"><span>                ApplicationArea = All;</span></span>
<span class="line"><span>                Image = Info;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                trigger OnAction()</span></span>
<span class="line"><span>                begin</span></span>
<span class="line"><span>                    Message(&#39;Customer: %1&#39;, Rec.Name);</span></span>
<span class="line"><span>                end;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here:</p><ul><li><code>actions</code> contains our action modifications.</li><li><code>addlast(Processing)</code> places the new action at the end of the existing Processing action area.</li><li><code>action(ShowCustomerInfo)</code> defines our new action.</li><li><code>OnAction()</code> executes when the user selects the action.</li></ul><p>We can also introduce entirely new action groups.</p><h2 id="modifying-existing-controls" tabindex="-1">Modifying Existing Controls <a class="header-anchor" href="#modifying-existing-controls" aria-label="Permalink to “Modifying Existing Controls”">​</a></h2><p>Sometimes, we don&#39;t need to introduce new fields or actions. We simply want to modify controls that already exist.</p><p>We use the <code>modify</code> keyword.</p><p>For example, let&#39;s change the caption of the existing Address 2 field on the Customer Card.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50101 CustomerCardExt extends &quot;Customer Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    layout</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        modify(&quot;Address 2&quot;)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            Caption = &#39;Additional Address&#39;;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The <code>modify</code> keyword identifies an existing control that we want to change.</p><p>We can modify supported properties of existing controls, such as:</p><ul><li><code>Caption</code></li><li><code>ToolTip</code></li><li><code>Visible</code></li><li><code>Enabled</code></li><li><code>Importance</code></li></ul><p><strong>Important:</strong> You cannot modify every property of an existing control. Only properties supported for modification through page extensions can be changed.</p><h2 id="repositioning-existing-controls" tabindex="-1">Repositioning Existing Controls <a class="header-anchor" href="#repositioning-existing-controls" aria-label="Permalink to “Repositioning Existing Controls”">​</a></h2><p>Page extensions also allow us to change the position of existing controls.</p><p>We use the following keywords:</p><table tabindex="0"><thead><tr><th>Keyword</th><th>Description</th></tr></thead><tbody><tr><td><code>addfirst</code></td><td>Adds a new control or action at the beginning of a group or area.</td></tr><tr><td><code>addlast</code></td><td>Adds a new control or action at the end of a group or area.</td></tr><tr><td><code>addafter</code></td><td>Adds a new control or action after an existing one.</td></tr><tr><td><code>addbefore</code></td><td>Adds a new control or action before an existing one.</td></tr><tr><td><code>movefirst</code></td><td>Moves an existing control or action to the beginning of a group or area.</td></tr><tr><td><code>movelast</code></td><td>Moves an existing control or action to the end of a group or area.</td></tr><tr><td><code>moveafter</code></td><td>Moves an existing control or action after another one.</td></tr><tr><td><code>movebefore</code></td><td>Moves an existing control or action before another one.</td></tr></tbody></table><h3 id="example-addafter" tabindex="-1">Example: addafter <a class="header-anchor" href="#example-addafter" aria-label="Permalink to “Example: addafter”">​</a></h3><p>Suppose we want to add a field immediately after the existing Name field.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>layout</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    addafter(Name)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        field(RewardPoints; Rec.RewardPoints)</span></span>
<span class="line"><span>        {</span></span>
<span class="line"><span>            ApplicationArea = All;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="example-moveafter" tabindex="-1">Example: moveafter <a class="header-anchor" href="#example-moveafter" aria-label="Permalink to “Example: moveafter”">​</a></h3><p>Suppose we want to move the existing Address field after the Name field.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>layout</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    moveafter(General; Name, Address)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Here, <code>General</code> is the group containing the controls, and <code>Name</code> and <code>Address</code> are the controls being repositioned.</p><p>The same positioning concepts apply to actions in the <code>actions</code> section.</p><h2 id="page-extension-triggers" tabindex="-1">Page Extension Triggers <a class="header-anchor" href="#page-extension-triggers" aria-label="Permalink to “Page Extension Triggers”">​</a></h2><p>Page extensions can also implement certain page triggers to introduce additional behavior.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pageextension 50101 CustomerCardExt extends &quot;Customer Card&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Customer Card opened!&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This displays a message when the Customer Card page opens.</p><p>You can also implement supported triggers such as <code>OnAfterGetRecord</code> and <code>OnAfterGetCurrRecord</code>.</p><p>However, page extensions do not support every trigger available in regular page objects. Always check the documentation for the specific trigger.</p><h2 id="_8-important-things-to-remember" tabindex="-1">8. Important Things to Remember <a class="header-anchor" href="#_8-important-things-to-remember" aria-label="Permalink to “8. Important Things to Remember”">​</a></h2><ul><li>Page extensions allow us to customize existing pages without modifying their original definitions.</li><li>Use <code>pageextension</code> to define a page extension.</li><li>The target page must be extensible.</li><li>Use <code>layout</code> to modify page controls.</li><li>Use <code>actions</code> to modify page actions.</li><li>Use <code>addfirst</code>, <code>addlast</code>, <code>addafter</code>, and <code>addbefore</code> to introduce new controls or actions at specific positions.</li><li>Use <code>modify</code> to change supported properties of existing controls.</li><li>Use <code>movefirst</code>, <code>movelast</code>, <code>moveafter</code>, and <code>movebefore</code> to reposition existing controls.</li><li>Use a table extension when you need to introduce additional database fields.</li></ul><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-page-ext-object" target="_blank" rel="noreferrer">Page Extension Object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-table-ext-object" target="_blank" rel="noreferrer">Table Extension Object</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/properties/devenv-extensible-property" target="_blank" rel="noreferrer">Extensible Property</a></li></ul>`,65)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};